S = {'mode': 'rev'}
def control(obs):
    h = obs['hitch_deg']
    st = obs['status']
    if S['mode'] == 'rev' and (st == 'JACKKNIFED' or abs(h) > 55):
        S['mode'] = 'fwd'
    if S['mode'] == 'fwd' and abs(h) < 12 and st != 'JACKKNIFED':
        S['mode'] = 'rev'
    if S['mode'] == 'fwd':
        return {'steer_deg': 0.0, 'speed_mps': 0.8}
    y = obs['rig']['trailer_rear'][1]
    hd = max(-20.0, min(20.0, 15.0 * (0.4 - y)))
    steer = max(-45.0, min(45.0, 2.5 * (h - hd)))
    return {'steer_deg': steer, 'speed_mps': -0.8}

